import { settlementSetupHTML } from './settlement-setup.js';
import { sourceGroups } from './source-selection.js';
import { DRAGONSGATE } from './render.js';
export function wizardMarkup() {
  return `<header class="world-header"><div><span class="eyebrow">REAL PLACE · FANTASY SETTLEMENT</span><h2 id="world-title">Build your fantasy map</h2></div><button class="icon-button" type="button" id="world-close" aria-label="Close world map">×</button></header>
    <nav class="world-steps" aria-label="Map creation steps">${['Choose a region','Keep what matters','Shape your settlement'].map((label,i)=>`<button type="button" data-world-tab="${i}" aria-current="${i===0?'step':'false'}" ${i?'disabled':''}><span>${i+1}</span>${label}</button>`).join('')}</nav>
    <div class="world-body"><form class="world-settings"><section data-world-step="0" aria-labelledby="world-region-title">
      <h3 id="world-region-title" tabindex="-1">Start with a real place</h3><p class="world-step-intro">Drag and zoom the map until the frame contains your whole settlement and its surroundings. Only the area inside the frame is used.</p>
      <label>Explore an example<select name="example"><option value="">Choose a place…</option><option value="iceland">Iceland · island shape for a city</option><option value="sicily">Sicily · island shape</option><option value="-3.191,55.950">Edinburgh · Old Town</option><option value="12.335,45.435">Venice · canals</option><option value="-89.384,43.074">Madison · Capitol</option></select></label>
      <details><summary>Go to coordinates</summary><div class="world-coordinates"><label>Latitude<input name="latitude" type="number" min="-85" max="85" step="any" value="20"></label><label>Longitude<input name="longitude" type="number" min="-180" max="180" step="any" value="0"></label></div><button type="button" class="button" id="world-go">Go to coordinates</button></details>
      <fieldset><legend>Image shape</legend><div class="world-shapes"><label><input type="radio" name="format" value="square" checked><span>□ Square</span></label><label><input type="radio" name="format" value="landscape"><span>▭ Landscape</span></label><label><input type="radio" name="format" value="portrait"><span>▯ Portrait</span></label></div></fieldset>
      <label>Image size<select name="edge"><option value="2048">2048 px · smaller file</option><option value="4096" selected>4096 px · recommended</option><option value="4800">4800 px · large export</option></select></label><p class="world-dimensions"></p><p>Resolution changes image detail, not the amount of land. Zoom out to include more surroundings.</p><div class="world-region-summary" role="status"></div><div class="world-scale-summary" aria-live="polite"></div><label class="world-checkbox"><input type="checkbox" name="reinterpret" checked> Resize broad shapes to settlement distances</label><p>Large outlines can become a town or city. Keep this on to use settlement distances instead of continent-scale travel distances.</p>
      <details><summary>Map view and data source</summary><label>Navigation map<select name="basemap"><option value="terrain">OpenTopoMap terrain</option><option value="street">OpenStreetMap streets</option></select></label><label>Map data<select name="dataSource"><option value="prepared">Prepared map data (recommended)</option><option value="live">Live OpenStreetMap data</option></select></label><p class="world-source-note">Prepared data is a March 2026 snapshot. Live data can be newer but public services may be busy.</p><p>Only moving forward loads feature data. Panning uses navigation tiles only.</p></details>
    </section>
    <section data-world-step="1" hidden aria-labelledby="world-source-title"><h3 id="world-source-title" tabindex="-1">Keep the useful geography</h3><p class="world-step-intro">Choose which mapped layers to use. The region’s size sets the available detail. Missing, unavailable or deselected layers are generated for your settlement. The preview shows retained source geometry before generation.</p><div class="world-source-choices">${Object.entries(sourceGroups).map(([key,p])=>`<label class="world-source-choice"><input type="checkbox" name="sourceGroup" value="${key}" checked ${key==='coast'?'disabled':''}><span><strong><i style="background:${p.color}" aria-hidden="true"></i>${p.label}</strong><small>${p.note}</small><small data-source-count="${key}">Reading region…</small></span></label>`).join('')}</div>
      <label>Building uses<select name="buildingUses"><option value="fantasy">Reimagine all uses for my settlement</option><option value="mapped">Use mapped shops, inns and temple hints</option></select></label><p>Reimagining keeps footprints and gives you control over fantasy sites in the next step. Mapped hints may retain additional sites.</p><details><summary>Leave out individual features</summary><p>Click a colored feature in the preview to leave it out. Click its faded outline to restore it. The coastline stays as the land silhouette. Rivers and lakes can be replaced. Turning off every feature in a layer lets the system generate that layer. Mapped tree marks are controlled as a group. You can also use the accessible list below.</p><label>Feature group<select id="world-feature-group">${Object.entries(sourceGroups).filter(([k])=>k!=='coast').map(([k,p])=>`<option value="${k}">${p.label}</option>`).join('')}</select></label><div class="world-feature-list"></div><div class="world-list-pages"><button type="button" class="button quiet" id="world-list-prev">Previous</button><span id="world-list-page"></span><button type="button" class="button quiet" id="world-list-next">Next</button></div><button type="button" class="button quiet" id="world-restore">Restore individual removals</button></details>
    </section>
    <section data-world-step="2" hidden aria-labelledby="world-settlement-title"><h3 id="world-settlement-title" tabindex="-1">Give the place a purpose</h3><label>Map name<input name="mapName" value="My new settlement" maxlength="100" required></label>${settlementSetupHTML()}
      <details><summary>Artwork and generation</summary><p>Pale parchment, ink buildings and hand drawn terrain. Modern source labels are removed.</p><div class="world-colors"><label>Land<input type="color" name="paper" value="${DRAGONSGATE.paper}"></label><label>Water<input type="color" name="water" value="${DRAGONSGATE.water}"></label><label>Ink<input type="color" name="ink" value="${DRAGONSGATE.ink}"></label></div><label>Road width<input type="range" name="roadWidth" min="0.6" max="1.8" step="0.1" value="1"></label><label>Tree and woodland density<input type="range" name="treeDensity" min="0" max="2" step="0.25" value="1"></label><label>Paper texture<input type="range" name="texture" min="0" max="1" step="0.05" value="0.35"></label><label class="world-checkbox"><input type="checkbox" name="roofDetail"> Add roof detail</label><button class="button quiet" type="button" id="world-reset">Reset style</button><label>Generation seed<input name="seed" value="world-map-v1" maxlength="128" required></label><p>The same region, seed and choices produce the same map.</p></details>
    </section></form>
    <section class="world-workspace" aria-label="Map selection and preview"><div class="world-view-tabs"><strong id="world-view-title">Frame your region</strong><span class="world-area"></span></div>
      <div class="world-map-panel"><div class="world-map" tabindex="0" role="region" aria-label="World map. Drag to pan. Scroll or pinch to zoom. Arrow keys pan. Plus and minus zoom."></div><div class="world-navigation"><button class="map-control" id="world-plus" aria-label="Zoom world map in">+</button><button class="map-control" id="world-minus" aria-label="Zoom world map out">−</button></div><div class="world-attribution">© <a href="https://www.openstreetmap.org/copyright" target="_blank" rel="noopener">OpenStreetMap</a>, SRTM · © <a href="https://opentopomap.org/about" target="_blank" rel="noopener">OpenTopoMap</a></div><p class="world-pan-help">Drag beneath the frame. Scroll or pinch to zoom.</p></div>
      <div class="world-source-art" hidden><canvas id="world-source-canvas" aria-label="Source geometry. Use the feature choices or individual feature list to choose what to retain."></canvas><p>Colored features are kept. Faded features are omitted. Layers with nothing retained are generated. Click a feature to toggle it.</p><p>© OpenStreetMap contributors · ODbL. Prepared data also uses Natural Earth and Protomaps.</p></div>
      <div class="world-art" hidden><canvas id="world-fantasy-canvas" aria-label="Fantasy map preview"></canvas><label class="world-preview-toggle"><input type="checkbox" id="world-preview-districts" checked> Show district boundaries for review</label><p>Boundary colors are a review overlay. The exported image omits this overlay.</p></div>
      <div class="world-plan" aria-live="polite" hidden></div><div class="world-review" hidden></div>
      <p class="world-status" role="status" aria-live="polite"><span class="world-message">Choose an example or zoom in to find your settlement.</span><span class="world-elapsed" aria-hidden="true" hidden></span></p>
    </section></div>
    <footer class="world-footer"><button type="button" class="button quiet" id="world-back" hidden>Back</button><span id="world-step-label">Step 1 of 3</span><button type="button" class="button primary" id="world-next">Read region & continue</button><button type="button" class="button" id="world-cancel" hidden>Cancel</button><button type="button" class="button" id="world-generate" hidden>Create fantasy preview</button><button type="button" class="button" id="world-download" hidden>PNG</button><button type="button" class="button" id="world-backup" hidden>Atlas backup</button><button type="button" class="button primary" id="world-save" hidden>Save and open map</button></footer>`;
}
